include "../lib/rosetta/faces.mlpl";
include "../lib/rosetta/scene.mlpl";
include "../demos/one-neuron/equation.mlpl";
ir = unwrap(u:on_equation());
s = u:rs_face_svg(ir, "math");
print(s);
print(u:rs_svg_strip_tags(unwrap(s)));
sc = u:rs_scene_new("t");
sc = unwrap(u:rs_scene_polyline(sc, reshape([0, 0, 0, 1, 0, 0, 1, 1, 0], [3, 3]), 1, "a", [1, 0, 0, 1]));
